'use client';

import { useState } from 'react';
import { 
  MagnifyingGlassIcon, PlusIcon, PencilIcon, TrashIcon, 
  TagIcon, Squares2X2Icon, DocumentDuplicateIcon 
} from '@heroicons/react/24/outline';
import { createDocumentType, updateDocumentType, deleteDocumentType } from '@/app/lib/actions';
import { motion } from 'framer-motion';

export default function DocumentTypesTable({ types, categories }: { types: any[], categories: any[] }) {
  const session = await auth();
  
  if ((session?.user as any)?.role !== 'admin') redirect('/dashboard');
  const [types, categories] = await Promise.all([getDocumentTypes(), getCategories()]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);
  const filtered = types.filter(t =>
    t.name.toLowerCase().includes(search.toLowerCase()) ||
    t.category_name?.toLowerCase().includes(search.toLowerCase())
  );
  
  return (
    <div>
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-slate-800">Jenis Dokumen</h1>
        <p className="text-sm text-slate-400 mt-1">Kelola jenis dokumen per kategori</p>
      </div>
      <DocumentTypesTable
        types={types as any}
        categories={categories as any}
      />
    </div>
  );
}
